const dataSourceId = "YOUR_NOTION_DATA_SOURCE_ID";
const statusOptionId = "YOUR_NOTION_STATUS_OPTION_ID";
function configuredNotionId(value, name) {
  if (
    typeof value !== "string" ||
    !/^(?:[0-9a-f]{32}|[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$/i.test(value)
  ) {
    throw new Error("Configure the destination " + name + " as its Notion ID");
  }
  return value;
}
function calendlyNotionRequest({ invitee, dataSourceId, statusOptionId }) {
  configuredNotionId(dataSourceId, "data source");
  if (
    typeof statusOptionId !== "string" ||
    !statusOptionId.trim() ||
    statusOptionId === "YOUR_NOTION_STATUS_OPTION_ID"
  ) {
    throw new Error("Configure an existing destination Status option ID");
  }
  if (
    !invitee ||
    typeof invitee !== "object" ||
    Array.isArray(invitee) ||
    typeof invitee.name !== "string" ||
    !invitee.name.trim() ||
    typeof invitee.email !== "string" ||
    !invitee.email.trim()
  ) {
    throw new Error("The Calendly booking must contain an invitee name and email");
  }
  return {
    parent: { type: "data_source_id", data_source_id: dataSourceId },
    properties: {
      Name: { title: [{ type: "text", text: { content: invitee.name } }] },
      Email: { email: invitee.email },
      Status: { select: { id: statusOptionId } },
    },
  };
}

return $input.all().flatMap((item, index) =>
  item.json.event === "invitee.created"
    ? [
        {
          json: calendlyNotionRequest({
            invitee: item.json.payload,
            dataSourceId,
            statusOptionId,
          }),
          pairedItem: { item: index },
        },
      ]
    : [],
);

function notionBookingCreated({ page }) {
  if (
    !page ||
    typeof page !== "object" ||
    Array.isArray(page) ||
    page.object !== "page" ||
    typeof page.id !== "string" ||
    !page.id.trim()
  ) {
    throw new Error("Notion did not return a created page ID");
  }
  return { page };
}

return { json: notionBookingCreated({ page: $json }).page };
